// Badge helpers
const sevBadge = (s) => {
  const m = { Critical:'#dc3545', High:'#fd7e14', Medium:'#ffc107', Low:'#6c757d' };
  return <span style={{ background:m[s]||'#adb5bd', color:'#fff', padding:'2px 8px', borderRadius:10, fontSize:10, fontWeight:700 }}>{s}</span>;
};
const priBadge = (p) => {
  const m = { P0:'#dc3545', P1:'#fd7e14', P2:'#0dcaf0', P3:'#6c757d' };
  return <span style={{ background:m[p]||'#adb5bd', color:'#fff', padding:'2px 8px', borderRadius:10, fontSize:10, fontWeight:700 }}>{p}</span>;
};
const typeBadge = (t) => {
  const m = { Functional:'#3498db', Security:'#e74c3c', Performance:'#e67e22', Integration:'#2ecc71', Negative:'#9b59b6' };
  return <span style={{ color:m[t]||'#6c757d', border:`1px solid ${m[t]||'#6c757d'}`, padding:'1px 6px', borderRadius:8, fontSize:9, fontWeight:600 }}>{t}</span>;
};

