// ---- Tab Config ----
const TABS = [
  { key:'integration', label:'DB Integration Testing', scenarios:DB_INTEGRATION },
  { key:'query', label:'Query Testing', scenarios:QUERY_TESTING },
  { key:'security', label:'DB Security Testing', scenarios:DB_SECURITY },
  { key:'apidata', label:'API Data Testing', scenarios:API_DATA },
];

// ---- Main Component ----
export default function DatabaseTestingFullLab() {
  const [activeTab, setActiveTab] = useState('integration');
  const [expanded, setExpanded] = useState({});
  const [search, setSearch] = useState('');

  const toggle = (id) => setExpanded(p => ({ ...p, [id]: !p[id] }));
  const tab = TABS.find(t => t.key === activeTab) || TABS[0];
  const scenarios = tab.scenarios.filter(s =>
    !search || s.title.toLowerCase().includes(search.toLowerCase()) || s.id.toLowerCase().includes(search.toLowerCase())
  );
  const allScenarios = TABS.flatMap(t => t.scenarios);

  // ---- Styles ----
  const page = { minHeight:'100vh', background:'#fff', color:'#212529', fontFamily:"'Segoe UI',Tahoma,Geneva,Verdana,sans-serif", padding:'18px 22px 40px' };
  const header = { fontSize:22, fontWeight:800, color:C.header, letterSpacing:0.5, marginBottom:12 };
  const statRow = { display:'flex', gap:10, flexWrap:'wrap', marginBottom:14 };
  const statBox = (color) => ({ background:C.statBg, border:`1px solid ${C.border}`, borderRadius:10, padding:'10px 18px', minWidth:120, textAlign:'center', borderLeft:`4px solid ${color}` });
  const statNum = { fontSize:20, fontWeight:800 };
  const statLabel = { fontSize:11, color:C.muted, marginTop:2 };
  const tabBar = { display:'flex', gap:6, flexWrap:'wrap', marginBottom:14 };
  const tabBtn = (a) => ({ padding:'7px 18px', borderRadius:8, border:a?`2px solid ${C.tabActive}`:`1px solid ${C.border}`, background:a?C.tabActive:C.tabInactive, color:a?'#fff':'#212529', fontWeight:a?700:500, fontSize:13, cursor:'pointer' });
  const searchBox = { padding:'7px 14px', borderRadius:8, border:`1px solid ${C.border}`, fontSize:13, width:260, marginBottom:14 };
  const card = { background:'#fff', border:`1px solid ${C.border}`, borderRadius:10, marginBottom:10, boxShadow:`0 1px 4px ${C.shadow}`, overflow:'hidden' };
  const cardHead = { display:'flex', alignItems:'center', justifyContent:'space-between', padding:'12px 16px', cursor:'pointer', gap:8 };
  const cardBody = { padding:'0 16px 14px', borderTop:`1px solid ${C.border}` };
  const section = { marginTop:10 };
  const secTitle = { fontSize:12, fontWeight:700, color:C.accent, marginBottom:4 };
  const stepItem = { fontSize:12, color:'#444', padding:'3px 0', display:'flex', gap:6 };
  const idBadge = { background:C.accent, color:'#fff', padding:'2px 8px', borderRadius:10, fontSize:10, fontWeight:700, whiteSpace:'nowrap' };

  // Stats
  const total = allScenarios.length;
  const crit = allScenarios.filter(s => s.severity === 'Critical').length;
  const high = allScenarios.filter(s => s.severity === 'High').length;
  const med = allScenarios.filter(s => s.severity === 'Medium').length;
  const p0 = allScenarios.filter(s => s.priority === 'P0').length;

  return (
    <div style={page}>
      <div style={header}>Database Testing Full Lab</div>

      {/* Stats */}
      <div style={statRow}>
        <div style={statBox(C.accent)}><div style={statNum}>{total}</div><div style={statLabel}>Total Scenarios</div></div>
        <div style={statBox('#dc3545')}><div style={{...statNum, color:'#dc3545'}}>{crit}</div><div style={statLabel}>Critical</div></div>
        <div style={statBox('#fd7e14')}><div style={{...statNum, color:'#fd7e14'}}>{high}</div><div style={statLabel}>High</div></div>
        <div style={statBox('#ffc107')}><div style={{...statNum, color:'#ffc107'}}>{med}</div><div style={statLabel}>Medium</div></div>
        <div style={statBox('#0d6efd')}><div style={{...statNum, color:'#0d6efd'}}>{p0}</div><div style={statLabel}>P0 Priority</div></div>
        <div style={statBox('#198754')}><div style={{...statNum, color:'#198754'}}>{TABS.length}</div><div style={statLabel}>Categories</div></div>
      </div>

      {/* Tabs */}
      <div style={tabBar}>
        {TABS.map(t => (
          <button key={t.key} style={tabBtn(activeTab === t.key)} onClick={() => { setActiveTab(t.key); setSearch(''); }}>
            {t.label} ({t.scenarios.length})
          </button>
        ))}
      </div>

      {/* Search */}
      <input style={searchBox} placeholder="Search by ID or title..." value={search} onChange={e => setSearch(e.target.value)} />

      {/* Scenario Cards */}
      <div>
        {scenarios.length === 0 && <div style={{ color:C.muted, fontSize:13, padding:20, textAlign:'center' }}>No scenarios match your search.</div>}
        {scenarios.map(s => (
          <div key={s.id} style={card}>
            <div style={cardHead} onClick={() => toggle(s.id)}>
              <div style={{ display:'flex', alignItems:'center', gap:8, flexWrap:'wrap', flex:1 }}>
                <span style={idBadge}>{s.id}</span>
                <span style={{ fontSize:14, fontWeight:600, color:'#212529' }}>{s.title}</span>
                {sevBadge(s.severity)}
                {priBadge(s.priority)}
                {typeBadge(s.type)}
              </div>
              <span style={{ fontSize:16, color:C.muted, transform: expanded[s.id] ? 'rotate(180deg)' : 'rotate(0deg)', transition:'transform 0.2s' }}>&#9660;</span>
            </div>

            {expanded[s.id] && (
              <div style={cardBody}>
                <div style={{ fontSize:12, color:'#555', marginTop:8, lineHeight:1.5 }}>{s.description}</div>

                <div style={section}>
                  <div style={secTitle}>Test Steps</div>
                  {s.steps.map((st, i) => (
                    <div key={i} style={stepItem}>
                      <span style={{ color:C.accent, fontWeight:700, minWidth:16 }}>{i + 1}.</span>
                      <span>{st}</span>
                    </div>
                  ))}
                </div>

                <div style={section}>
                  <div style={secTitle}>Expected Result</div>
                  <div style={{ fontSize:12, color:'#444', lineHeight:1.5 }}>{s.expectedResult}</div>
                </div>

                <div style={section}>
                  <div style={secTitle}>Test Data</div>
                  <div style={{ fontSize:11, color:'#666', background:'#f8f9fa', padding:'6px 10px', borderRadius:6, fontFamily:'monospace' }}>{s.testData}</div>
                </div>
                <TestRunnerButtons scenarioId={s.id} scenarioTitle={s.title} isManual={(s.tab || '').toLowerCase().includes('manual')} />
              </div>
            )}
          </div>
        ))}
      </div>
      <TestHistoryPanel scenarios={[...DB_INTEGRATION, ...QUERY_TESTING, ...DB_SECURITY, ...API_DATA]} pageKey="database-testing-full-lab" />
    </div>
  );
}
