// ─── HELPERS ───

const statusColor = (s) => {
  const m = { Pass: S.pass, Fail: S.fail, Blocked: S.blocked, 'Not Run': S.notRun, 'In Progress': S.inProgress };
  return m[s] || S.notRun;
};

const pctColor = (p) => p >= 90 ? S.pass : p >= 75 ? '#e65100' : S.fail;

const rate = (p, t) => t ? Math.round((p / t) * 100) : 0;

const Bar = ({ pct, color, h = 8 }) => (
  <div style={{ background: '#e9ecef', borderRadius: h / 2, height: h, width: '100%', overflow: 'hidden' }}>
    <div style={{ width: pct + '%', height: '100%', background: color || pctColor(pct), borderRadius: h / 2, transition: 'width 0.4s ease' }} />
  </div>
);

const Badge = ({ status }) => {
  const bg = { pass: '#e8f5e9', fail: '#ffebee', warn: '#fff3e0' };
  const fg = { pass: S.pass, fail: S.fail, warn: '#e65100' };
  const st = status || 'pass';
  return (
    <span style={{ background: bg[st] || bg.pass, color: fg[st] || fg.pass, padding: '2px 10px', borderRadius: 12, fontSize: 12, fontWeight: 600 }}>
      {st === 'pass' ? 'PASS' : st === 'fail' ? 'FAIL' : 'WARN'}
    </span>
  );
};

const StatCard = ({ label, value, color }) => (
  <div style={{ background: C.statBg, borderRadius: 10, padding: '14px 18px', flex: 1, minWidth: 160, textAlign: 'center', border: '1px solid #e2e8f0' }}>
    <div style={{ fontSize: 13, color: C.muted, marginBottom: 4 }}>{label}</div>
    <div style={{ fontSize: 26, fontWeight: 700, color: color || C.accent }}>{value}</div>
  </div>
);

