/* ─── Stats per tab ─── */
const getTabStats = (tab) => {
  const items = SCENARIOS.filter(s => s.tab === tab);
  const crit = items.filter(s => s.severity === 'Critical').length;
  const high = items.filter(s => s.severity === 'High').length;
  const p0 = items.filter(s => s.priority === 'P0').length;
  return { total: items.length, crit, high, p0 };
};

export default function CodeTestingLab() {
  const [activeTab, setActiveTab] = useState('CodeQuality');
  const [expanded, setExpanded] = useState({});
  const [search, setSearch] = useState('');

  const toggle = (id) => setExpanded(prev => ({ ...prev, [id]: !prev[id] }));

  const filtered = SCENARIOS.filter(s => s.tab === activeTab && (
    !search || s.id.toLowerCase().includes(search.toLowerCase()) ||
    s.title.toLowerCase().includes(search.toLowerCase()) ||
    s.type.toLowerCase().includes(search.toLowerCase())
  ));

  const stats = getTabStats(activeTab);

  return (
    <div style={{ minHeight: '100vh', background: '#ffffff', fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif", padding: '18px 22px 40px', color: C.text }}>
      {/* Header */}
      <div style={{ textAlign: 'center', marginBottom: 18 }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: C.header, margin: 0 }}>Code Testing Lab</h1>
        <p style={{ fontSize: 13, color: C.muted, margin: '4px 0 0' }}>Banking QA - 48 Scenarios across 6 Categories</p>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 14, flexWrap: 'wrap', justifyContent: 'center' }}>
        {TABS.map(t => (
          <button key={t.key} onClick={() => { setActiveTab(t.key); setSearch(''); }}
            style={{ padding: '8px 16px', fontSize: 13, fontWeight: 600, border: 'none', borderRadius: 6, cursor: 'pointer',
              background: activeTab === t.key ? C.tabActive : C.tabInactive,
              color: activeTab === t.key ? '#fff' : C.muted,
              boxShadow: activeTab === t.key ? `0 2px 8px ${C.shadow}` : 'none',
              transition: 'all 0.2s' }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* Stats Bar */}
      <div style={{ display: 'flex', gap: 10, marginBottom: 14, flexWrap: 'wrap', justifyContent: 'center' }}>
        {[
          { label: 'Total', value: stats.total, color: C.accent },
          { label: 'Critical', value: stats.crit, color: SEV_COLORS.Critical },
          { label: 'High', value: stats.high, color: SEV_COLORS.High },
          { label: 'P0', value: stats.p0, color: PRI_COLORS.P0 },
        ].map((st, i) => (
          <div key={i} style={{ background: C.statBg, borderRadius: 8, padding: '8px 18px', textAlign: 'center', minWidth: 80 }}>
            <div style={{ fontSize: 20, fontWeight: 700, color: st.color }}>{st.value}</div>
            <div style={{ fontSize: 11, color: C.muted }}>{st.label}</div>
          </div>
        ))}
      </div>

      {/* Search */}
      <div style={{ maxWidth: 420, margin: '0 auto 16px', position: 'relative' }}>
        <input value={search} onChange={e => setSearch(e.target.value)}
          placeholder="Search by ID, title, or type..."
          style={{ width: '100%', padding: '9px 14px', fontSize: 13, border: `1px solid ${C.border}`, borderRadius: 8,
            outline: 'none', background: '#fff', color: C.text, boxSizing: 'border-box' }} />
        {search && (
          <span onClick={() => setSearch('')} style={{ position: 'absolute', right: 12, top: '50%', transform: 'translateY(-50%)',
            cursor: 'pointer', color: C.muted, fontSize: 16 }}>x</span>
        )}
      </div>

      {/* Scenario Cards */}
      <div style={{ maxWidth: 900, margin: '0 auto' }}>
        {filtered.length === 0 && (
          <div style={{ textAlign: 'center', padding: 40, color: C.muted, fontSize: 14 }}>No scenarios match your search.</div>
        )}
        {filtered.map(sc => {
          const isOpen = expanded[sc.id];
          return (
            <div key={sc.id} style={{ background: '#fff', border: `1px solid ${C.border}`, borderRadius: 10,
              marginBottom: 10, boxShadow: `0 1px 4px ${C.shadow}`, overflow: 'hidden', transition: 'box-shadow 0.2s' }}>
              {/* Card Header */}
              <div onClick={() => toggle(sc.id)}
                style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 16px', cursor: 'pointer',
                  flexWrap: 'wrap' }}>
                {/* ID Badge */}
                <span style={{ background: C.accent, color: '#fff', fontSize: 11, fontWeight: 700, padding: '3px 8px',
                  borderRadius: 4, whiteSpace: 'nowrap', letterSpacing: 0.5 }}>{sc.id}</span>
                {/* Title */}
                <span style={{ flex: 1, fontSize: 14, fontWeight: 600, color: C.textWhite, minWidth: 150 }}>{sc.title}</span>
                {/* Badges */}
                <span style={{ background: SEV_COLORS[sc.severity], color: '#fff', fontSize: 10, fontWeight: 600,
                  padding: '2px 8px', borderRadius: 10 }}>{sc.severity}</span>
                <span style={{ background: PRI_COLORS[sc.priority], color: '#fff', fontSize: 10, fontWeight: 600,
                  padding: '2px 8px', borderRadius: 10 }}>{sc.priority}</span>
                <span style={{ background: C.statBg, color: C.accent, fontSize: 10, fontWeight: 600,
                  padding: '2px 8px', borderRadius: 10, border: `1px solid ${C.border}` }}>{sc.type}</span>
                {/* Expand arrow */}
                <span style={{ fontSize: 14, color: C.muted, transition: 'transform 0.2s',
                  transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>&#9660;</span>
              </div>

              {/* Expanded Content */}
              {isOpen && (
                <div style={{ padding: '0 16px 14px', borderTop: `1px solid ${C.border}` }}>
                  {/* Description */}
                  <div style={{ margin: '12px 0 10px' }}>
                    <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: 'uppercase', marginBottom: 4 }}>Description</div>
                    <div style={{ fontSize: 13, color: C.text, lineHeight: 1.5 }}>{sc.description}</div>
                  </div>

                  {/* Steps */}
                  <div style={{ margin: '0 0 10px' }}>
                    <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: 'uppercase', marginBottom: 4 }}>Test Steps</div>
                    <div style={{ fontSize: 13, color: C.text, lineHeight: 1.7, background: C.statBg, padding: '10px 14px',
                      borderRadius: 6, whiteSpace: 'pre-line' }}>{sc.steps}</div>
                  </div>

                  {/* Expected Result */}
                  <div style={{ margin: '0 0 10px' }}>
                    <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: 'uppercase', marginBottom: 4 }}>Expected Result</div>
                    <div style={{ fontSize: 13, color: C.success, lineHeight: 1.5, background: '#f0fdf4', padding: '8px 12px',
                      borderRadius: 6, border: '1px solid #bbf7d0' }}>{sc.expectedResult}</div>
                  </div>

                  {/* Test Data */}
                  <div>
                    <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: 'uppercase', marginBottom: 4 }}>Test Data</div>
                    <div style={{ fontSize: 12, color: C.muted, background: '#f8f9fa', padding: '8px 12px',
                      borderRadius: 6, border: `1px solid ${C.border}`, fontFamily: 'monospace' }}>{sc.testData}</div>
                  </div>
                  <TestRunnerButtons scenarioId={sc.id} scenarioTitle={sc.title} isManual={(sc.tab || '').toLowerCase().includes('manual')} />
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Footer */}
      <div style={{ textAlign: 'center', marginTop: 24, fontSize: 11, color: C.muted }}>
        Code Testing Lab - {SCENARIOS.length} Scenarios - Banking QA Dashboard
      </div>
      <TestHistoryPanel scenarios={SCENARIOS} pageKey="code-testing-lab" />
    </div>
  );
}
