// ─── COLLAPSIBLE CARD COMPONENT ───
function CollapsibleCard({ title, defaultOpen = false, children, accentColor = C.accent }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div style={{
      background: '#ffffff',
      border: `1px solid ${C.border}`,
      borderRadius: 10,
      marginBottom: 16,
      boxShadow: `0 2px 8px ${C.shadow}`,
      overflow: 'hidden',
    }}>
      <div
        onClick={() => setOpen(!open)}
        style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '14px 20px', cursor: 'pointer',
          background: open ? C.statBg : '#ffffff',
          borderBottom: open ? `1px solid ${C.border}` : 'none',
          transition: 'background 0.2s',
        }}
      >
        <span style={{
          fontWeight: 700, fontSize: 16, color: C.text,
          display: 'flex', alignItems: 'center', gap: 8,
        }}>
          <span style={{
            display: 'inline-block', width: 4, height: 20,
            background: accentColor, borderRadius: 2, marginRight: 6,
          }} />
          {title}
        </span>
        <span style={{
          fontSize: 18, color: C.muted, transform: open ? 'rotate(180deg)' : 'rotate(0deg)',
          transition: 'transform 0.2s', userSelect: 'none',
        }}>
          &#9660;
        </span>
      </div>
      {open && (
        <div style={{ padding: '18px 20px' }}>
          {children}
        </div>
      )}
    </div>
  );
}

// ─── STAT BADGE ───
function StatBadge({ label, value, color }) {
  return (
    <div style={{
      display: 'inline-flex', flexDirection: 'column', alignItems: 'center',
      background: C.statBg, borderRadius: 8, padding: '12px 22px', minWidth: 90,
      border: `1px solid ${C.border}`,
    }}>
      <span style={{ fontSize: 24, fontWeight: 800, color }}>{value}</span>
      <span style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>{label}</span>
    </div>
  );
}

// ─── PRIORITY BADGE ───
function PriorityBadge({ priority }) {
  const colors = { P0: C.danger, P1: C.warn, P2: C.info };
  return (
    <span style={{
      display: 'inline-block', background: colors[priority] || C.muted,
      color: '#fff', fontSize: 11, fontWeight: 700, borderRadius: 4,
      padding: '2px 8px', marginLeft: 8, letterSpacing: 0.5,
    }}>
      {priority}
    </span>
  );
}

