// ---------------------------------------------------------------------------
// Severity & Category Badge Helpers
// ---------------------------------------------------------------------------
const severityBadge = (sev) => {
  const map = {
    Critical: { bg: '#dc3545', label: 'Critical' },
    High:     { bg: '#fd7e14', label: 'High' },
    Medium:   { bg: '#ffc107', label: 'Medium' },
    Low:      { bg: '#6c757d', label: 'Low' },
  };
  const c = map[sev] || { bg: '#adb5bd', label: sev || '?' };
  return (
    <span style={{ background: c.bg, color: '#fff', padding: '2px 8px', borderRadius: 10, fontSize: 10, fontWeight: 700 }}>
      {c.label}
    </span>
  );
};

const categoryBadge = (cat) => (
  <span style={{ color: C.accent, border: `1px solid ${C.accent}`, padding: '2px 8px', borderRadius: 10, fontSize: 10, fontWeight: 600 }}>
    {cat}
  </span>
);

const testTypeBadge = (type) => {
  const map = { schema: '#3498db', count: '#2ecc71', quality: '#9b59b6', performance: '#e67e22' };
  const color = map[type] || '#6c757d';
  return (
    <span style={{ color, border: `1px solid ${color}`, padding: '1px 6px', borderRadius: 8, fontSize: 9, fontWeight: 600 }}>
      {type}
    </span>
  );
};

