// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------
export default function DataTestingLab() {
  // ---- State ----
  const [activeTab, setActiveTab] = useState('ingestion');
  const [selectedScenarioId, setSelectedScenarioId] = useState(null);
  const [rightTab, setRightTab] = useState('manual');
  const [searchQuery, setSearchQuery] = useState('');

  // Persisted state: manual test results, step checks, notes, automated test results
  const [manualResults, setManualResults] = useState({});   // { scenarioId: 'pass'|'fail'|'block' }
  const [stepChecks, setStepChecks] = useState({});         // { scenarioId: { 0: true, 1: false, ... } }
  const [notes, setNotes] = useState({});                   // { scenarioId: 'text' }
  const [autoResults, setAutoResults] = useState({});        // { testId: 'pass'|'fail'|'pending'|'running' }
  const [runningTests, setRunningTests] = useState({});      // { testId: true }

  // ---- Load from localStorage ----
  useEffect(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const data = JSON.parse(saved);
        if (data.manualResults) setManualResults(data.manualResults);
        if (data.stepChecks) setStepChecks(data.stepChecks);
        if (data.notes) setNotes(data.notes);
        if (data.autoResults) setAutoResults(data.autoResults);
        if (data.activeTab) setActiveTab(data.activeTab);
        if (data.selectedScenarioId) setSelectedScenarioId(data.selectedScenarioId);
      }
    } catch (_) { /* ignore parse errors */ }
  }, []);

  // ---- Persist to localStorage ----
  const persist = useCallback((mr, sc, nt, ar, at, sid) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        manualResults: mr, stepChecks: sc, notes: nt, autoResults: ar, activeTab: at, selectedScenarioId: sid,
      }));
    } catch (_) { /* ignore quota errors */ }
  }, []);

  useEffect(() => {
    persist(manualResults, stepChecks, notes, autoResults, activeTab, selectedScenarioId);
  }, [manualResults, stepChecks, notes, autoResults, activeTab, selectedScenarioId, persist]);

  // ---- Derived ----
  const currentTab = TABS.find(t => t.key === activeTab) || TABS[0];
  const filteredScenarios = currentTab.scenarios.filter(s =>
    !searchQuery || s.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.category.toLowerCase().includes(searchQuery.toLowerCase())
  );
  const selectedScenario = currentTab.scenarios.find(s => s.id === selectedScenarioId) || null;

  // Auto-select first scenario when switching tabs or when none selected
  useEffect(() => {
    if (!selectedScenarioId || !currentTab.scenarios.find(s => s.id === selectedScenarioId)) {
      if (currentTab.scenarios.length > 0) {
        setSelectedScenarioId(currentTab.scenarios[0].id);
      }
    }
  }, [activeTab, currentTab.scenarios, selectedScenarioId]);

  // ---- Handlers ----
  const handleSetManualResult = (scenarioId, status) => {
    setManualResults(prev => ({ ...prev, [scenarioId]: prev[scenarioId] === status ? undefined : status }));
  };

  const handleToggleStep = (scenarioId, stepIdx) => {
    setStepChecks(prev => ({
      ...prev,
      [scenarioId]: { ...(prev[scenarioId] || {}), [stepIdx]: !(prev[scenarioId] || {})[stepIdx] },
    }));
  };

  const handleSetNotes = (scenarioId, text) => {
    setNotes(prev => ({ ...prev, [scenarioId]: text }));
  };

  const runSingleTest = (testId) => {
    if (runningTests[testId]) return;
    setRunningTests(prev => ({ ...prev, [testId]: true }));
    setAutoResults(prev => ({ ...prev, [testId]: 'running' }));
    const delay = 1000 + Math.random() * 1000;
    setTimeout(() => {
      const result = Math.random() > 0.3 ? 'pass' : 'fail';
      setAutoResults(prev => ({ ...prev, [testId]: result }));
      setRunningTests(prev => { const n = { ...prev }; delete n[testId]; return n; });
    }, delay);
  };

  const runAllTests = (scenario) => {
    if (!scenario) return;
    scenario.automatedTests.forEach(t => runSingleTest(t.id));
  };

  // ---- Progress Calculations ----
  const allScenarios = TABS.flatMap(t => t.scenarios);
  const totalScenarios = allScenarios.length;
  const testedCount = allScenarios.filter(s => manualResults[s.id]).length;
  const passCount = allScenarios.filter(s => manualResults[s.id] === 'pass').length;
  const failCount = allScenarios.filter(s => manualResults[s.id] === 'fail').length;
  const blockCount = allScenarios.filter(s => manualResults[s.id] === 'block').length;
  const progressPct = totalScenarios > 0 ? Math.round((testedCount / totalScenarios) * 100) : 0;

  // ---- Auto test summary for selected scenario ----
  const autoTestSummary = (scenario) => {
    if (!scenario) return { total: 0, passed: 0 };
    const total = scenario.automatedTests.length;
    const passed = scenario.automatedTests.filter(t => autoResults[t.id] === 'pass').length;
    return { total, passed };
  };

  // ---- Styles ----
  const pageStyle = {
    minHeight: '100vh',
    background: '#ffffff',
    color: '#212529',
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    padding: '18px 22px 12px',
    display: 'flex',
    flexDirection: 'column',
  };

  const headerStyle = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 16,
    flexWrap: 'wrap',
    gap: 10,
  };

  const titleStyle = {
    fontSize: 22,
    fontWeight: 800,
    color: C.header,
    letterSpacing: 0.5,
  };

  const tabBarStyle = {
    display: 'flex',
    gap: 6,
    flexWrap: 'wrap',
  };

  const tabBtnStyle = (isActive) => ({
    padding: '7px 18px',
    borderRadius: 8,
    border: isActive ? `2px solid ${C.tabActive}` : `1px solid ${C.border}`,
    background: isActive ? C.tabActive : C.tabInactive,
    color: isActive ? '#fff' : '#212529',
    fontWeight: isActive ? 700 : 500,
    fontSize: 13,
    cursor: 'pointer',
    transition: 'all 0.2s ease',
  });

  const splitContainerStyle = {
    display: 'flex',
    flex: 1,
    gap: 16,
    minHeight: 0,
    overflow: 'hidden',
  };

  const leftPanelStyle = {
    width: '40%',
    minWidth: 300,
    display: 'flex',
    flexDirection: 'column',
    border: `1px solid ${C.border}`,
    borderRadius: 10,
    background: '#ffffff',
    boxShadow: `0 2px 8px ${C.shadow}`,
    overflow: 'hidden',
  };

  const rightPanelStyle = {
    width: '60%',
    display: 'flex',
    flexDirection: 'column',
    border: `1px solid ${C.border}`,
    borderRadius: 10,
    background: '#ffffff',
    boxShadow: `0 2px 8px ${C.shadow}`,
    overflow: 'hidden',
  };

  const searchInputStyle = {
    width: '100%',
    padding: '10px 14px',
    border: 'none',
    borderBottom: `1px solid ${C.border}`,
    fontSize: 13,
    outline: 'none',
    background: '#f8f9fa',
    color: '#212529',
    boxSizing: 'border-box',
  };

  const scenarioListStyle = {
    flex: 1,
    overflowY: 'auto',
    padding: '6px 0',
  };

  const scenarioItemStyle = (isSelected) => ({
    padding: '12px 14px',
    cursor: 'pointer',
    borderLeft: isSelected ? `4px solid ${C.accent}` : '4px solid transparent',
    background: isSelected ? '#f0f4ff' : '#ffffff',
    transition: 'all 0.15s ease',
    borderBottom: `1px solid #f0f0f0`,
  });

  const rightTabBarStyle = {
    display: 'flex',
    borderBottom: `1px solid ${C.border}`,
    background: '#f8f9fa',
  };

  const rightTabBtnStyle = (isActive) => ({
    flex: 1,
    padding: '10px 16px',
    border: 'none',
    borderBottom: isActive ? `3px solid ${C.accent}` : '3px solid transparent',
    background: 'transparent',
    color: isActive ? C.accent : '#6c757d',
    fontWeight: isActive ? 700 : 500,
    fontSize: 13,
    cursor: 'pointer',
    transition: 'all 0.2s ease',
  });

  const statusBtnStyle = (type, currentStatus) => {
    const colorMap = { pass: '#198754', fail: '#dc3545', block: '#fd7e14' };
    const isActive = currentStatus === type;
    return {
      padding: '6px 18px',
      borderRadius: 6,
      border: `2px solid ${colorMap[type]}`,
      background: isActive ? colorMap[type] : 'transparent',
      color: isActive ? '#fff' : colorMap[type],
      fontWeight: 700,
      fontSize: 12,
      cursor: 'pointer',
      transition: 'all 0.2s ease',
    };
  };

  const autoTestResultBadge = (status) => {
    const map = {
      pass: { bg: '#198754', label: 'Pass' },
      fail: { bg: '#dc3545', label: 'Fail' },
      running: { bg: '#6c757d', label: 'Running...' },
    };
    const c = map[status] || { bg: '#dee2e6', label: 'Pending' };
    return (
      <span style={{ background: c.bg, color: status ? '#fff' : '#6c757d', padding: '2px 10px', borderRadius: 8, fontSize: 11, fontWeight: 700 }}>
        {c.label}
      </span>
    );
  };

  const progressBarStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: 16,
    padding: '14px 18px',
    marginTop: 16,
    border: `1px solid ${C.border}`,
    borderRadius: 10,
    background: '#ffffff',
    boxShadow: `0 2px 8px ${C.shadow}`,
    flexWrap: 'wrap',
  };

  // ---- Render ----
  return (
    <div style={pageStyle}>
      {/* Header with title and tabs */}
      <div style={headerStyle}>
        <div style={titleStyle}>Data Testing Lab</div>
        <div style={tabBarStyle}>
          {TABS.map(tab => (
            <button
              key={tab.key}
              style={tabBtnStyle(activeTab === tab.key)}
              onClick={() => { setActiveTab(tab.key); setSearchQuery(''); }}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Split Panel */}
      <div style={splitContainerStyle}>
        {/* Left Panel: Scenario List */}
        <div style={leftPanelStyle}>
          <input
            type="text"
            placeholder="Search scenarios..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            style={searchInputStyle}
          />
          <div style={scenarioListStyle}>
            {filteredScenarios.length === 0 && (
              <div style={{ padding: 20, textAlign: 'center', color: '#6c757d', fontSize: 13 }}>
                No scenarios match your search.
              </div>
            )}
            {filteredScenarios.map(scenario => {
              const isSelected = selectedScenarioId === scenario.id;
              const result = manualResults[scenario.id];
              return (
                <div
                  key={scenario.id}
                  style={scenarioItemStyle(isSelected)}
                  onClick={() => setSelectedScenarioId(scenario.id)}
                  onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = '#f8f9fa'; }}
                  onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = '#ffffff'; }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                    <span style={{ fontSize: 12, fontWeight: 700, color: C.accent }}>{scenario.id}</span>
                    {result && (
                      <span style={{
                        width: 8, height: 8, borderRadius: '50%', display: 'inline-block',
                        background: result === 'pass' ? '#198754' : result === 'fail' ? '#dc3545' : '#fd7e14',
                      }} />
                    )}
                  </div>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#212529', marginBottom: 6 }}>
                    {scenario.title}
                  </div>
                  <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                    {severityBadge(scenario.severity)}
                    {categoryBadge(scenario.category)}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Right Panel */}
        <div style={rightPanelStyle}>
          {/* Right Panel Tabs */}
          <div style={rightTabBarStyle}>
            <button style={rightTabBtnStyle(rightTab === 'manual')} onClick={() => setRightTab('manual')}>
              Manual Testing
            </button>
            <button style={rightTabBtnStyle(rightTab === 'automated')} onClick={() => setRightTab('automated')}>
              Automated Testing
            </button>
          </div>

          {/* Right Panel Content */}
          <div style={{ flex: 1, overflowY: 'auto', padding: 18 }}>
            {!selectedScenario ? (
              <div style={{ textAlign: 'center', color: '#6c757d', padding: 40, fontSize: 14 }}>
                Select a scenario from the left panel to view details.
              </div>
            ) : rightTab === 'manual' ? (
              /* ---- Manual Testing Tab ---- */
              <div>
                {/* Scenario Header */}
                <div style={{ marginBottom: 18 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: C.accent }}>{selectedScenario.id}</span>
                    {severityBadge(selectedScenario.severity)}
                    {categoryBadge(selectedScenario.category)}
                  </div>
                  <div style={{ fontSize: 18, fontWeight: 700, color: '#212529', marginBottom: 8 }}>
                    {selectedScenario.title}
                  </div>
                  <div style={{ fontSize: 13, color: '#495057', lineHeight: 1.6 }}>
                    {selectedScenario.description}
                  </div>
                </div>

                {/* Test Steps Checklist */}
                <div style={{ marginBottom: 18 }}>
                  <div style={{ fontSize: 14, fontWeight: 700, color: '#212529', marginBottom: 10, borderBottom: `2px solid ${C.accent}`, paddingBottom: 4, display: 'inline-block' }}>
                    Test Steps
                  </div>
                  {selectedScenario.steps.map((step, idx) => {
                    const checked = (stepChecks[selectedScenario.id] || {})[idx] || false;
                    return (
                      <label
                        key={idx}
                        style={{
                          display: 'flex', alignItems: 'flex-start', gap: 10, padding: '8px 10px', marginBottom: 4,
                          background: checked ? '#f0fff4' : '#f8f9fa', borderRadius: 6, cursor: 'pointer',
                          border: `1px solid ${checked ? '#c3e6cb' : '#e9ecef'}`, transition: 'all 0.2s ease',
                        }}
                      >
                        <input
                          type="checkbox"
                          checked={checked}
                          onChange={() => handleToggleStep(selectedScenario.id, idx)}
                          style={{ marginTop: 3, accentColor: C.accent, width: 16, height: 16 }}
                        />
                        <span style={{ fontSize: 13, color: checked ? '#155724' : '#212529', textDecoration: checked ? 'line-through' : 'none', lineHeight: 1.5 }}>
                          <strong>Step {idx + 1}:</strong> {step}
                        </span>
                      </label>
                    );
                  })}
                </div>

                {/* Expected Result */}
                <div style={{ marginBottom: 18 }}>
                  <div style={{ fontSize: 14, fontWeight: 700, color: '#212529', marginBottom: 8, borderBottom: `2px solid #198754`, paddingBottom: 4, display: 'inline-block' }}>
                    Expected Result
                  </div>
                  <div style={{ fontSize: 13, color: '#495057', lineHeight: 1.6, padding: '10px 14px', background: '#f0fff4', borderRadius: 6, border: '1px solid #c3e6cb' }}>
                    {selectedScenario.expectedResult}
                  </div>
                </div>

                {/* Status Buttons */}
                <div style={{ marginBottom: 18 }}>
                  <div style={{ fontSize: 14, fontWeight: 700, color: '#212529', marginBottom: 10, borderBottom: `2px solid #fd7e14`, paddingBottom: 4, display: 'inline-block' }}>
                    Test Status
                  </div>
                  <div style={{ display: 'flex', gap: 10, marginTop: 4 }}>
                    {['pass', 'fail', 'block'].map(status => (
                      <button
                        key={status}
                        style={statusBtnStyle(status, manualResults[selectedScenario.id])}
                        onClick={() => handleSetManualResult(selectedScenario.id, status)}
                      >
                        {status === 'pass' ? 'Pass' : status === 'fail' ? 'Fail' : 'Block'}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Notes */}
                <div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: '#212529', marginBottom: 8, borderBottom: `2px solid #6c757d`, paddingBottom: 4, display: 'inline-block' }}>
                    Tester Notes
                  </div>
                  <textarea
                    value={notes[selectedScenario.id] || ''}
                    onChange={e => handleSetNotes(selectedScenario.id, e.target.value)}
                    placeholder="Add testing notes, observations, defect references..."
                    style={{
                      width: '100%', minHeight: 80, padding: '10px 14px', borderRadius: 6,
                      border: `1px solid ${C.border}`, fontSize: 13, resize: 'vertical',
                      outline: 'none', fontFamily: 'inherit', color: '#212529', background: '#f8f9fa',
                      boxSizing: 'border-box',
                    }}
                  />
                </div>
                <TestRunnerButtons scenarioId={selectedScenario.id} scenarioTitle={selectedScenario.title} isManual={true} />
              </div>
            ) : (
              /* ---- Automated Testing Tab ---- */
              <div>
                {/* Scenario Header */}
                <div style={{ marginBottom: 18 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: C.accent }}>{selectedScenario.id}</span>
                    {severityBadge(selectedScenario.severity)}
                  </div>
                  <div style={{ fontSize: 18, fontWeight: 700, color: '#212529', marginBottom: 8 }}>
                    {selectedScenario.title} - Automated Tests
                  </div>
                </div>

                {/* Run All Button + Summary */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 18 }}>
                  <button
                    onClick={() => runAllTests(selectedScenario)}
                    style={{
                      padding: '8px 22px', borderRadius: 6, border: `2px solid ${C.accent}`,
                      background: C.accent, color: '#fff', fontWeight: 700, fontSize: 13,
                      cursor: 'pointer', transition: 'all 0.2s ease',
                    }}
                    onMouseEnter={e => { e.currentTarget.style.background = '#0b5ed7'; }}
                    onMouseLeave={e => { e.currentTarget.style.background = C.accent; }}
                  >
                    Run All Tests
                  </button>
                  <span style={{ fontSize: 13, color: '#495057' }}>
                    {autoTestSummary(selectedScenario).passed}/{autoTestSummary(selectedScenario).total} tests passed
                  </span>
                </div>

                {/* Auto Test List */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {selectedScenario.automatedTests.map(test => {
                    const result = autoResults[test.id];
                    const isRunning = runningTests[test.id];
                    return (
                      <div
                        key={test.id}
                        style={{
                          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                          padding: '12px 14px', borderRadius: 8,
                          background: result === 'pass' ? '#f0fff4' : result === 'fail' ? '#fff5f5' : '#f8f9fa',
                          border: `1px solid ${result === 'pass' ? '#c3e6cb' : result === 'fail' ? '#f5c6cb' : '#e9ecef'}`,
                          transition: 'all 0.2s ease',
                        }}
                      >
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, flex: 1 }}>
                          <span style={{ fontSize: 11, fontWeight: 700, color: '#6c757d' }}>{test.id}</span>
                          <span style={{ fontSize: 13, fontWeight: 600, color: '#212529' }}>{test.name}</span>
                          {testTypeBadge(test.type)}
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                          {autoTestResultBadge(result)}
                          {!isRunning && (
                            <button
                              onClick={() => runSingleTest(test.id)}
                              style={{
                                padding: '4px 12px', borderRadius: 4, border: `1px solid ${C.accent}`,
                                background: 'transparent', color: C.accent, fontWeight: 600, fontSize: 11,
                                cursor: 'pointer', transition: 'all 0.15s ease',
                              }}
                              onMouseEnter={e => { e.currentTarget.style.background = C.accent; e.currentTarget.style.color = '#fff'; }}
                              onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = C.accent; }}
                            >
                              Run
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
                <TestRunnerButtons scenarioId={selectedScenario.id} scenarioTitle={selectedScenario.title} isManual={false} />
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Bottom Progress Bar */}
      <div style={progressBarStyle}>
        <div style={{ fontSize: 13, fontWeight: 700, color: '#212529', minWidth: 200 }}>
          Progress: {testedCount}/{totalScenarios} scenarios tested
        </div>
        <div style={{ flex: 1, minWidth: 200 }}>
          <div style={{ width: '100%', background: '#e9ecef', borderRadius: 6, overflow: 'hidden', height: 10 }}>
            <div style={{
              width: `${progressPct}%`, height: '100%', borderRadius: 6,
              background: `linear-gradient(90deg, ${C.accent}, #198754)`,
              transition: 'width 0.5s ease',
            }} />
          </div>
        </div>
        <span style={{ fontSize: 13, fontWeight: 700, color: '#212529' }}>{progressPct}%</span>
        <div style={{ display: 'flex', gap: 14, marginLeft: 8 }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: '#198754' }}>Pass: {passCount}</span>
          <span style={{ fontSize: 12, fontWeight: 700, color: '#dc3545' }}>Fail: {failCount}</span>
          <span style={{ fontSize: 12, fontWeight: 700, color: '#fd7e14' }}>Block: {blockCount}</span>
        </div>
      </div>
      <TestHistoryPanel scenarios={allScenarios.map(s => ({ id: s.id, title: s.title }))} pageKey="data-testing-lab" />
    </div>
  );
}
