const badge = (text, bg) => ({
  display: 'inline-block', padding: '2px 10px', borderRadius: 12, fontSize: 11,
  fontWeight: 700, color: '#fff', background: bg, marginRight: 6, letterSpacing: 0.3,
});

export default function AgentTestingLab() {
  const [activeTab, setActiveTab] = useState('chatbot');
  const [expandedCards, setExpandedCards] = useState({});
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSeverity, setFilterSeverity] = useState('All');

  const toggle = (id) => setExpandedCards((p) => ({ ...p, [id]: !p[id] }));

  const filtered = useMemo(() => {
    return scenarios.filter((s) => {
      if (s.tab !== activeTab) return false;
      if (filterSeverity !== 'All' && s.severity !== filterSeverity) return false;
      if (searchTerm) {
        const q = searchTerm.toLowerCase();
        return s.id.toLowerCase().includes(q) || s.title.toLowerCase().includes(q) || s.description.toLowerCase().includes(q);
      }
      return true;
    });
  }, [activeTab, filterSeverity, searchTerm]);

  const tabCounts = useMemo(() => {
    const counts = {};
    TABS.forEach((t) => { counts[t.key] = scenarios.filter((s) => s.tab === t.key).length; });
    return counts;
  }, []);

  const sevCounts = useMemo(() => {
    const c = { Critical: 0, High: 0, Medium: 0, Low: 0 };
    scenarios.forEach((s) => { if (c[s.severity] !== undefined) c[s.severity]++; });
    return c;
  }, []);

  return (
    <div style={{ minHeight: '100vh', background: '#ffffff', color: C.text, fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif", padding: '18px 22px 40px' }}>
      {/* Header */}
      <div style={{ marginBottom: 18, borderBottom: '2px solid ' + C.border, paddingBottom: 14 }}>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: C.header, margin: 0 }}>Agent Testing Lab</h1>
        <p style={{ color: C.muted, fontSize: 14, margin: '4px 0 0' }}>
          Banking QA Testing Dashboard — AI Chatbot, RPA, Workflow, Manual, and Automation Agent Testing Scenarios
        </p>
      </div>

      {/* Stats Row */}
      <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', marginBottom: 16 }}>
        {[
          { label: 'Total Scenarios', value: scenarios.length, color: C.accent },
          { label: 'Critical', value: sevCounts.Critical, color: SEV.Critical },
          { label: 'High', value: sevCounts.High, color: SEV.High },
          { label: 'Medium', value: sevCounts.Medium, color: SEV.Medium },
          { label: 'Low', value: sevCounts.Low, color: SEV.Low },
        ].map((st) => (
          <div key={st.label} style={{ background: C.statBg, border: '1px solid ' + C.border, borderRadius: 8, padding: '10px 18px', minWidth: 110, textAlign: 'center', boxShadow: '0 1px 4px ' + C.shadow }}>
            <div style={{ fontSize: 22, fontWeight: 800, color: st.color }}>{st.value}</div>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600 }}>{st.label}</div>
          </div>
        ))}
      </div>

      {/* Search + Filter */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 14, flexWrap: 'wrap' }}>
        <input
          type="text"
          placeholder="Search scenarios by ID, title, or description..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ flex: 1, minWidth: 220, padding: '8px 14px', border: '1px solid ' + C.border, borderRadius: 6, fontSize: 13, outline: 'none', background: '#fff', color: C.text }}
        />
        <select
          value={filterSeverity}
          onChange={(e) => setFilterSeverity(e.target.value)}
          style={{ padding: '8px 14px', border: '1px solid ' + C.border, borderRadius: 6, fontSize: 13, background: '#fff', color: C.text, cursor: 'pointer' }}
        >
          <option value="All">All Severities</option>
          <option value="Critical">Critical</option>
          <option value="High">High</option>
          <option value="Medium">Medium</option>
          <option value="Low">Low</option>
        </select>
      </div>

      {/* Tab Bar */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 18, flexWrap: 'wrap', borderBottom: '2px solid ' + C.border, paddingBottom: 0 }}>
        {TABS.map((t) => (
          <button
            key={t.key}
            onClick={() => setActiveTab(t.key)}
            style={{
              padding: '9px 16px', border: 'none', borderBottom: activeTab === t.key ? '3px solid ' + C.tabActive : '3px solid transparent',
              background: C.tabInactive, color: activeTab === t.key ? C.tabActive : C.muted,
              fontWeight: activeTab === t.key ? 700 : 500, fontSize: 13, cursor: 'pointer', borderRadius: '6px 6px 0 0', transition: 'all 0.15s',
            }}
          >
            {t.label}
            <span style={{ marginLeft: 6, background: activeTab === t.key ? C.tabActive : '#e0e0e0', color: activeTab === t.key ? '#fff' : '#555', borderRadius: 10, padding: '1px 8px', fontSize: 11, fontWeight: 700 }}>
              {tabCounts[t.key]}
            </span>
          </button>
        ))}
      </div>

      {/* Scenario Cards */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {filtered.length === 0 && (
          <div style={{ textAlign: 'center', padding: 40, color: C.muted, fontSize: 14 }}>No scenarios match your search/filter criteria.</div>
        )}
        {filtered.map((s) => {
          const open = expandedCards[s.id];
          return (
            <div key={s.id} style={{ background: '#fff', border: '1px solid ' + C.border, borderRadius: 8, boxShadow: '0 1px 4px ' + C.shadow, overflow: 'hidden' }}>
              {/* Card Header */}
              <div
                onClick={() => toggle(s.id)}
                style={{ display: 'flex', alignItems: 'center', padding: '12px 16px', cursor: 'pointer', gap: 10, flexWrap: 'wrap' }}
              >
                <span style={{ fontSize: 14, transition: 'transform 0.2s', transform: open ? 'rotate(90deg)' : 'rotate(0deg)', color: C.muted, flexShrink: 0 }}>&#9654;</span>
                <span style={{ fontWeight: 700, fontSize: 12, color: C.accent, minWidth: 80, flexShrink: 0 }}>{s.id}</span>
                <span style={{ fontWeight: 600, fontSize: 13, color: C.textWhite, flex: 1 }}>{s.title}</span>
                <span style={badge(s.severity, SEV[s.severity] || '#78909c')}>{s.severity}</span>
                <span style={badge(s.priority, PRI[s.priority] || '#0dcaf0')}>{s.priority}</span>
                <span style={badge(s.type, '#455a64')}>{s.type}</span>
              </div>

              {/* Expanded Content */}
              {open && (
                <div style={{ padding: '0 16px 14px', borderTop: '1px solid ' + C.border }}>
                  <div style={{ margin: '10px 0 8px', fontSize: 13, color: '#444', lineHeight: 1.6 }}>{s.description}</div>

                  <div style={{ fontWeight: 700, fontSize: 12, color: C.accent, marginBottom: 4 }}>Steps:</div>
                  <ol style={{ margin: '0 0 10px 18px', padding: 0, fontSize: 12, color: '#444', lineHeight: 1.8 }}>
                    {s.steps.map((st, i) => <li key={i}>{st}</li>)}
                  </ol>

                  <div style={{ fontWeight: 700, fontSize: 12, color: '#198754', marginBottom: 2 }}>Expected Result:</div>
                  <div style={{ fontSize: 12, color: '#444', marginBottom: 10, lineHeight: 1.6 }}>{s.expectedResult}</div>

                  <div style={{ fontWeight: 700, fontSize: 12, color: '#7b1fa2', marginBottom: 2 }}>Test Data:</div>
                  <div style={{ fontSize: 12, color: '#555', background: '#f8f9fa', padding: '8px 12px', borderRadius: 6, fontFamily: 'monospace', lineHeight: 1.6, wordBreak: 'break-word' }}>{s.testData}</div>
                  <TestRunnerButtons scenarioId={s.id} scenarioTitle={s.title} isManual={(s.tab || '').toLowerCase().includes('manual')} />
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Summary Footer */}
      <div style={{ marginTop: 22, padding: '14px 18px', background: C.statBg, border: '1px solid ' + C.border, borderRadius: 8, display: 'flex', flexWrap: 'wrap', gap: 16, alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: C.header }}>
          Total: {scenarios.length} Scenarios across {TABS.length} categories
        </div>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          {TABS.map((t) => (
            <span key={t.key} style={{ fontSize: 11, color: C.muted, fontWeight: 600 }}>
              {t.label}: <strong style={{ color: C.accent }}>{tabCounts[t.key]}</strong>
            </span>
          ))}
        </div>
      </div>
      <TestHistoryPanel scenarios={scenarios} pageKey="agent-testing-lab" />
    </div>
  );
}
