import React, { useState, useEffect, useCallback, useRef } from 'react';

const STORAGE_KEY = 'bankingQA_testHistory';
const SCHEDULE_KEY = 'bankingQA_scheduledJobs';

function getHistory() {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); }
  catch { return {}; }
}
function saveHistory(h) { localStorage.setItem(STORAGE_KEY, JSON.stringify(h)); }
function getSchedules() {
  try { return JSON.parse(localStorage.getItem(SCHEDULE_KEY) || '{}'); }
  catch { return {}; }
}
function saveSchedules(s) { localStorage.setItem(SCHEDULE_KEY, JSON.stringify(s)); }

const ST = { Pass: '#2e7d32', Fail: '#c62828', Blocked: '#e65100', Skipped: '#78909c', Running: '#1565c0' };

export default function TestRunnerButtons({ scenarioId, scenarioTitle, isManual }) {
  const [result, setResult] = useState(null);
  const [running, setRunning] = useState(false);
  const [marking, setMarking] = useState(null); // which manual button is active
  const [history, setHistory] = useState([]);
  const [notes, setNotes] = useState('');
  const [showHistory, setShowHistory] = useState(false);
  const [scheduled, setScheduled] = useState(false);
  const [flash, setFlash] = useState(null); // flash result animation

  useEffect(() => {
    const h = getHistory();
    if (h[scenarioId]) {
      setResult(h[scenarioId].result);
      setHistory(h[scenarioId].runs || []);
      setNotes(h[scenarioId].notes || '');
    }
    const sc = getSchedules();
    if (sc[scenarioId]) setScheduled(true);
  }, [scenarioId]);

  const addRun = useCallback((res, type) => {
    const run = { result: res, type, timestamp: new Date().toISOString(), scenarioId, scenarioTitle };
    const h = getHistory();
    if (!h[scenarioId]) h[scenarioId] = { runs: [] };
    h[scenarioId].result = res;
    h[scenarioId].runs = [run, ...(h[scenarioId].runs || [])].slice(0, 20);
    h[scenarioId].notes = notes;
    saveHistory(h);
    setResult(res);
    setHistory(h[scenarioId].runs);
    setFlash(res);
    setTimeout(() => setFlash(null), 1500);
  }, [scenarioId, scenarioTitle, notes]);

  const runAutoTest = useCallback(() => {
    if (isManual || running) return;
    setRunning(true);
    setResult(null);
    setTimeout(() => {
      const res = Math.random() > 0.2 ? 'Pass' : 'Fail';
      addRun(res, 'Automated');
      setRunning(false);
    }, 1000 + Math.random() * 1500);
  }, [isManual, running, addRun]);

  const markManual = useCallback((res) => {
    if (marking) return;
    setMarking(res);
    setTimeout(() => {
      addRun(res, 'Manual');
      setMarking(null);
    }, 600);
  }, [marking, addRun]);

  const toggleSchedule = useCallback(() => {
    const sc = getSchedules();
    if (sc[scenarioId]) {
      delete sc[scenarioId];
      setScheduled(false);
    } else {
      sc[scenarioId] = { scenarioId, scenarioTitle, scheduledAt: new Date().toISOString(), interval: 'daily' };
      setScheduled(true);
    }
    saveSchedules(sc);
  }, [scenarioId, scenarioTitle]);

  const saveNotes = useCallback(() => {
    const h = getHistory();
    if (!h[scenarioId]) h[scenarioId] = { runs: [] };
    h[scenarioId].notes = notes;
    saveHistory(h);
  }, [scenarioId, notes]);

  const allDisabled = running || marking !== null;

  const btnStyle = (bg, isActive, isDisabled) => ({
    padding: '7px 16px',
    fontSize: 12,
    fontWeight: 700,
    color: isDisabled ? '#868e96' : '#fff',
    background: isDisabled ? '#dee2e6' : isActive ? bg : bg,
    border: isDisabled ? '1px solid #ced4da' : '2px solid transparent',
    borderRadius: 6,
    cursor: isDisabled ? 'not-allowed' : 'pointer',
    opacity: isDisabled ? 0.6 : 1,
    transition: 'all 0.3s ease',
    whiteSpace: 'nowrap',
    transform: isActive ? 'scale(0.95)' : 'scale(1)',
    boxShadow: isActive ? 'inset 0 2px 4px rgba(0,0,0,0.2)' : 'none',
    position: 'relative',
    overflow: 'hidden',
  });

  const badge = (bg) => ({
    display: 'inline-block', padding: '4px 12px', fontSize: 12, fontWeight: 700, color: '#fff',
    background: bg, borderRadius: 6, letterSpacing: 0.5,
  });

  const flashBg = flash === 'Pass' ? 'rgba(46,125,50,0.08)' : flash === 'Fail' ? 'rgba(198,40,40,0.08)' : flash === 'Blocked' ? 'rgba(230,81,0,0.08)' : 'transparent';

  return (
    <div style={{
      marginTop: 16, borderTop: '1px dashed #dee2e6', paddingTop: 14,
      background: flashBg, borderRadius: 8, transition: 'background 0.5s ease',
      padding: '14px 12px',
    }}>
      {/* Action Row */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 10 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: '#495057', textTransform: 'uppercase', letterSpacing: 0.5, marginRight: 4 }}>
          {isManual ? 'Manual Testing:' : 'Test Actions:'}
        </span>

        {/* Auto Test Button */}
        {!isManual && (
          <button
            onClick={runAutoTest}
            disabled={allDisabled}
            style={{
              ...btnStyle('#0d6efd', running, running),
              background: running ? '#adb5bd' : '#0d6efd',
              color: running ? '#495057' : '#fff',
              minWidth: 120,
            }}
          >
            {running && (
              <span style={{
                display: 'inline-block', width: 12, height: 12, border: '2px solid #fff',
                borderTop: '2px solid transparent', borderRadius: '50%', marginRight: 6,
                animation: 'spin 1s linear infinite', verticalAlign: 'middle',
              }} />
            )}
            {running ? 'Running...' : 'Run Auto Test'}
          </button>
        )}

        {/* Manual Marking Buttons */}
        {[
          { label: 'Pass', color: '#2e7d32' },
          { label: 'Fail', color: '#c62828' },
          { label: 'Blocked', color: '#e65100' },
          { label: 'Skip', color: '#78909c', value: 'Skipped' },
        ].map(({ label, color, value }) => {
          const res = value || label;
          const isThisActive = marking === res;
          const isDisabled = allDisabled && !isThisActive;
          return (
            <button
              key={label}
              onClick={() => markManual(res)}
              disabled={isDisabled}
              style={{
                ...btnStyle(color, isThisActive, isDisabled),
                background: isThisActive ? '#adb5bd' : isDisabled ? '#dee2e6' : color,
                color: isThisActive ? '#495057' : isDisabled ? '#868e96' : '#fff',
              }}
            >
              {isThisActive ? 'Saving...' : label}
            </button>
          );
        })}

        {/* Schedule Button */}
        {!isManual && (
          <button
            onClick={toggleSchedule}
            disabled={allDisabled}
            style={{
              ...btnStyle(scheduled ? '#6f42c1' : '#6c757d', false, allDisabled),
              background: allDisabled ? '#dee2e6' : scheduled ? '#6f42c1' : '#6c757d',
              color: allDisabled ? '#868e96' : '#fff',
              borderStyle: scheduled ? 'solid' : 'dashed',
              borderColor: scheduled ? '#6f42c1' : '#adb5bd',
              borderWidth: 1,
            }}
          >
            {scheduled ? 'Scheduled' : 'Schedule'}
          </button>
        )}

        {/* Result Badge with animation */}
        {result && (
          <span style={{
            ...badge(ST[result] || '#6c757d'),
            transition: 'all 0.3s ease',
            transform: flash ? 'scale(1.15)' : 'scale(1)',
          }}>
            {result}
          </span>
        )}

        {/* History Toggle */}
        <button
          onClick={() => setShowHistory(!showHistory)}
          disabled={allDisabled}
          style={{
            padding: '7px 14px', fontSize: 12, fontWeight: 700,
            color: showHistory ? '#0d6efd' : '#495057',
            background: showHistory ? '#e7f1ff' : 'transparent',
            border: '1px solid ' + (showHistory ? '#0d6efd' : '#dee2e6'),
            borderRadius: 6, cursor: allDisabled ? 'not-allowed' : 'pointer',
            opacity: allDisabled ? 0.6 : 1,
            transition: 'all 0.2s',
          }}
        >
          History ({history.length})
        </button>
      </div>

      {/* Notes */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8 }}>
        <input
          type="text"
          placeholder="Add test notes..."
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          onBlur={saveNotes}
          style={{
            flex: 1, padding: '7px 12px', fontSize: 12, border: '1px solid #dee2e6',
            borderRadius: 6, outline: 'none', background: '#f8f9fa', color: '#212529',
            transition: 'border-color 0.2s',
          }}
        />
      </div>

      {/* History Table */}
      {showHistory && history.length > 0 && (
        <div style={{ marginTop: 8, maxHeight: 200, overflowY: 'auto', borderRadius: 8, border: '1px solid #e9ecef' }}>
          <table style={{ width: '100%', fontSize: 12, borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ background: '#f1f3f5' }}>
                <th style={{ padding: '6px 10px', textAlign: 'left', borderBottom: '2px solid #dee2e6', fontWeight: 700, color: '#495057' }}>#</th>
                <th style={{ padding: '6px 10px', textAlign: 'left', borderBottom: '2px solid #dee2e6', fontWeight: 700, color: '#495057' }}>Result</th>
                <th style={{ padding: '6px 10px', textAlign: 'left', borderBottom: '2px solid #dee2e6', fontWeight: 700, color: '#495057' }}>Type</th>
                <th style={{ padding: '6px 10px', textAlign: 'left', borderBottom: '2px solid #dee2e6', fontWeight: 700, color: '#495057' }}>Timestamp</th>
              </tr>
            </thead>
            <tbody>
              {history.map((r, i) => (
                <tr key={i} style={{ background: i % 2 === 0 ? '#ffffff' : '#f8f9fa' }}>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef' }}>{i + 1}</td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef' }}>
                    <span style={badge(ST[r.result] || '#6c757d')}>{r.result}</span>
                  </td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef', color: '#6c757d' }}>{r.type}</td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef', color: '#6c757d', fontFamily: 'monospace' }}>
                    {new Date(r.timestamp).toLocaleString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* CSS Animation for spinner */}
      <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

/* Page-level Test History Panel */
export function TestHistoryPanel({ scenarios, pageKey }) {
  const [history, setHistory] = useState({});
  const [showPanel, setShowPanel] = useState(false);
  const [runningAll, setRunningAll] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0 });
  const cancelRef = useRef(false);

  useEffect(() => {
    const h = getHistory();
    const filtered = {};
    (scenarios || []).forEach(s => { if (h[s.id]) filtered[s.id] = h[s.id]; });
    setHistory(filtered);
  }, [scenarios]);

  const tested = Object.keys(history).length;
  const passed = Object.values(history).filter(h => h.result === 'Pass').length;
  const failed = Object.values(history).filter(h => h.result === 'Fail').length;
  const blocked = Object.values(history).filter(h => h.result === 'Blocked').length;
  const total = (scenarios || []).length;
  const passRate = tested > 0 ? Math.round((passed / tested) * 100) : 0;

  const allRuns = [];
  Object.entries(history).forEach(([id, data]) => {
    (data.runs || []).forEach(run => { allRuns.push({ ...run, scenarioId: id }); });
  });
  allRuns.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  const exportReport = () => {
    const report = {
      page: pageKey,
      generatedAt: new Date().toISOString(),
      summary: { total, tested, passed, failed, blocked, passRate: passRate + '%' },
      scenarios: (scenarios || []).map(s => ({
        id: s.id, title: s.title,
        result: history[s.id]?.result || 'Not Run',
        lastRun: history[s.id]?.runs?.[0]?.timestamp || null,
        notes: history[s.id]?.notes || '',
        runCount: history[s.id]?.runs?.length || 0,
      })),
      recentRuns: allRuns.slice(0, 50),
    };
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = pageKey + '_test_report_' + new Date().toISOString().slice(0, 10) + '.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const runAllAuto = useCallback(() => {
    const autoScenarios = (scenarios || []).filter(s => {
      const tab = (s.tab || '').toLowerCase();
      return !tab.includes('manual');
    });
    if (autoScenarios.length === 0) return;
    setRunningAll(true);
    cancelRef.current = false;
    setProgress({ current: 0, total: autoScenarios.length });
    let idx = 0;
    const runNext = () => {
      if (idx >= autoScenarios.length || cancelRef.current) {
        setRunningAll(false);
        const h = getHistory();
        const filtered = {};
        (scenarios || []).forEach(sc => { if (h[sc.id]) filtered[sc.id] = h[sc.id]; });
        setHistory(filtered);
        return;
      }
      const s = autoScenarios[idx];
      const res = Math.random() > 0.2 ? 'Pass' : 'Fail';
      const run = { result: res, type: 'Automated', timestamp: new Date().toISOString(), scenarioId: s.id, scenarioTitle: s.title };
      const h = getHistory();
      if (!h[s.id]) h[s.id] = { runs: [] };
      h[s.id].result = res;
      h[s.id].runs = [run, ...(h[s.id].runs || [])].slice(0, 20);
      saveHistory(h);
      idx++;
      setProgress({ current: idx, total: autoScenarios.length });
      setTimeout(runNext, 300);
    };
    runNext();
  }, [scenarios]);

  const stopAll = () => { cancelRef.current = true; };

  const clearHistory = () => {
    const h = getHistory();
    (scenarios || []).forEach(s => { delete h[s.id]; });
    saveHistory(h);
    setHistory({});
  };

  const refresh = () => {
    const h = getHistory();
    const filtered = {};
    (scenarios || []).forEach(s => { if (h[s.id]) filtered[s.id] = h[s.id]; });
    setHistory(filtered);
  };

  const panelBtn = (bg, disabled) => ({
    padding: '7px 16px', fontSize: 12, fontWeight: 700,
    color: disabled ? '#868e96' : '#fff',
    background: disabled ? '#dee2e6' : bg,
    border: 'none', borderRadius: 6,
    cursor: disabled ? 'not-allowed' : 'pointer',
    opacity: disabled ? 0.6 : 1,
    transition: 'all 0.3s ease',
    whiteSpace: 'nowrap',
  });

  return (
    <div style={{ marginTop: 32, borderTop: '3px solid #0d6efd', paddingTop: 20 }}>
      {/* Summary Bar */}
      <div style={{
        display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap', marginBottom: 16,
        padding: '16px 20px', background: '#f0f4ff', borderRadius: 10,
      }}>
        <span style={{ fontSize: 16, fontWeight: 800, color: '#1a1a2e' }}>Test Dashboard</span>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 13, fontWeight: 700, color: '#495057' }}>Total: {total}</span>
          <span style={{ fontSize: 13, fontWeight: 700, color: '#1565c0' }}>Tested: {tested}</span>
          <span style={{ fontSize: 13, fontWeight: 700, color: '#2e7d32' }}>Pass: {passed}</span>
          <span style={{ fontSize: 13, fontWeight: 700, color: '#c62828' }}>Fail: {failed}</span>
          <span style={{ fontSize: 13, fontWeight: 700, color: '#e65100' }}>Blocked: {blocked}</span>
          <span style={{ fontSize: 13, fontWeight: 700, color: passRate >= 80 ? '#2e7d32' : passRate >= 50 ? '#e65100' : '#c62828' }}>
            Rate: {passRate}%
          </span>
        </div>
        {/* Progress Bar */}
        <div style={{ flex: 1, minWidth: 120 }}>
          <div style={{ height: 8, background: '#dee2e6', borderRadius: 4, overflow: 'hidden' }}>
            <div style={{ width: (tested / Math.max(total, 1) * 100) + '%', height: '100%', background: '#0d6efd', borderRadius: 4, transition: 'width 0.3s' }} />
          </div>
          {runningAll && (
            <div style={{ fontSize: 11, color: '#0d6efd', fontWeight: 700, marginTop: 4 }}>
              Running: {progress.current}/{progress.total}
            </div>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {!runningAll ? (
            <button onClick={runAllAuto} style={panelBtn('#0d6efd', false)}>Run All Auto</button>
          ) : (
            <button onClick={stopAll} style={panelBtn('#dc3545', false)}>Stop</button>
          )}
          <button onClick={refresh} disabled={runningAll} style={panelBtn('#495057', runningAll)}>Refresh</button>
          <button onClick={exportReport} disabled={runningAll} style={panelBtn('#198754', runningAll)}>Export Report</button>
          <button
            onClick={() => setShowPanel(!showPanel)}
            style={{
              padding: '7px 16px', fontSize: 12, fontWeight: 700,
              color: showPanel ? '#0d6efd' : '#495057',
              background: showPanel ? '#e7f1ff' : '#fff',
              border: '1px solid ' + (showPanel ? '#0d6efd' : '#dee2e6'),
              borderRadius: 6, cursor: 'pointer', transition: 'all 0.2s',
            }}
          >
            {showPanel ? 'Hide' : 'Show'} History
          </button>
          <button onClick={clearHistory} disabled={runningAll} style={panelBtn('#dc3545', runningAll)}>Clear</button>
        </div>
      </div>

      {/* Scenario Results Table */}
      {showPanel && (
        <div style={{ overflowX: 'auto' }}>
          <h3 style={{ fontSize: 15, fontWeight: 700, color: '#1a1a2e', margin: '0 0 10px' }}>Scenario Results</h3>
          <table style={{ width: '100%', fontSize: 12, borderCollapse: 'collapse', marginBottom: 20 }}>
            <thead>
              <tr style={{ background: '#1a1a2e' }}>
                {['ID', 'Title', 'Status', 'Last Run', 'Runs', 'Notes'].map(h => (
                  <th key={h} style={{ padding: '8px 12px', textAlign: 'left', color: '#fff', fontWeight: 700, fontSize: 11, textTransform: 'uppercase', letterSpacing: 0.5 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {(scenarios || []).map((s, i) => {
                const h = history[s.id];
                const res = h?.result || 'Not Run';
                const col = ST[res] || '#78909c';
                return (
                  <tr key={s.id} style={{ background: i % 2 === 0 ? '#ffffff' : '#f8f9fa', transition: 'background 0.2s' }}>
                    <td style={{ padding: '6px 12px', borderBottom: '1px solid #e9ecef', fontFamily: 'monospace', fontWeight: 700, color: '#0d6efd' }}>{s.id}</td>
                    <td style={{ padding: '6px 12px', borderBottom: '1px solid #e9ecef', maxWidth: 300 }}>{s.title}</td>
                    <td style={{ padding: '6px 12px', borderBottom: '1px solid #e9ecef' }}>
                      <span style={{ display: 'inline-block', padding: '3px 10px', fontSize: 11, fontWeight: 700, color: '#fff', background: col, borderRadius: 5, transition: 'all 0.3s' }}>{res}</span>
                    </td>
                    <td style={{ padding: '6px 12px', borderBottom: '1px solid #e9ecef', fontFamily: 'monospace', color: '#6c757d', fontSize: 11 }}>
                      {h?.runs?.[0]?.timestamp ? new Date(h.runs[0].timestamp).toLocaleString() : '-'}
                    </td>
                    <td style={{ padding: '6px 12px', borderBottom: '1px solid #e9ecef', textAlign: 'center', fontWeight: 700 }}>{h?.runs?.length || 0}</td>
                    <td style={{ padding: '6px 12px', borderBottom: '1px solid #e9ecef', color: '#6c757d', fontSize: 11 }}>{h?.notes || '-'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {/* Recent Activity */}
          <h3 style={{ fontSize: 15, fontWeight: 700, color: '#1a1a2e', margin: '0 0 10px' }}>Recent Activity</h3>
          <table style={{ width: '100%', fontSize: 12, borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ background: '#f1f3f5' }}>
                {['#', 'Scenario', 'Result', 'Type', 'Timestamp'].map(h => (
                  <th key={h} style={{ padding: '6px 10px', textAlign: 'left', borderBottom: '2px solid #dee2e6', fontWeight: 700, color: '#495057' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {allRuns.slice(0, 30).map((r, i) => (
                <tr key={i} style={{ background: i % 2 === 0 ? '#ffffff' : '#f8f9fa' }}>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef' }}>{i + 1}</td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef', fontFamily: 'monospace', fontSize: 11, color: '#0d6efd' }}>{r.scenarioId}</td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef' }}>
                    <span style={{ display: 'inline-block', padding: '2px 8px', fontSize: 11, fontWeight: 700, color: '#fff', background: ST[r.result] || '#78909c', borderRadius: 4 }}>{r.result}</span>
                  </td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef', color: '#6c757d' }}>{r.type}</td>
                  <td style={{ padding: '5px 10px', borderBottom: '1px solid #e9ecef', color: '#6c757d', fontFamily: 'monospace', fontSize: 11 }}>
                    {new Date(r.timestamp).toLocaleString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
